package app.streamnest;
import android.app.*;import android.content.*;import android.os.*;import java.util.*;import org.json.*;import org.libtorrent4j.*;
final class WatchedStartupRegression {
 static Bundle run(PlaybackRegression test)throws Exception{Context c=test.getTargetContext();WatchSync.pending=true;WatchSync.testPairingCode="";MainActivity[] main={null};TitleScreen[] dialog={null};SessionManager session=null;
 try{Catalog.Title title=Catalog.parse(new JSONObject().put("imdb","tt99001001").put("title","Manual watched fixture").put("genres",new JSONArray().put("drama")),"movies");HomeLibrary.cached=new ArrayList<>(Arrays.asList(title));HomeLibrary.cachedAt=System.currentTimeMillis();main[0]=(MainActivity)test.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Thread.sleep(700);
 JSONObject before=WatchProgress.records(c);test.runOnMainSync(()->{dialog[0]=new TitleScreen(main[0],title);dialog[0].show();dialog[0].watched.performClick();});HomeRegression.check(ManualWatched.isWatched(c,title.id),"Watched control did not save");HomeRegression.check(WatchProgress.records(c).toString().equals(before.toString()),"Manual watched modified resume history");test.runOnMainSync(()->dialog[0].watched.performClick());HomeRegression.check(!ManualWatched.isWatched(c,title.id),"Unwatched control did not save tombstone");test.runOnMainSync(()->dialog[0].dismiss());
 session=new SafeTorrentSession();session.start(new SessionParams(new SettingsPack().connectionsLimit(16).maxPeerlistSize(200).activeDownloads(1)));HomeRegression.check(((SafeTorrentSession)session).shutdownGuardInstalled,"Shutdown guard not installed");HomeRegression.check(session.settings().connectionsLimit()==16,"Initial native session ignored low-memory limits");session.stop();session=null;
 TorrentEngine held=new TorrentEngine();held.startup.begin("Stopping previous torrent session",1);Thread.sleep(5);StreamService.startupOwner=held;
 Intent request=new Intent(c,StreamService.class).putExtra("source","magnet:?xt=urn:btih:"+"a".repeat(40)).putExtra("imdb","tt99001001");test.runOnMainSync(()->c.startForegroundService(request));Thread.sleep(500);HomeRegression.check(StreamService.engine!=null&&StreamService.engine.closed&&StreamService.engine.message.contains("Previous torrent operation"),"Busy startup queued another session");HomeRegression.check(held.closed,"Superseded startup was not cancelled");StreamService.startupOwner=null;test.runOnMainSync(()->c.stopService(new Intent(c,StreamService.class)));
 if(test.manualSyncCode!=null){WatchSync.testPairingCode=test.manualSyncCode;JSONObject beforeSync=WatchProgress.records(c);ManualWatched.sync(c,test.manualSyncCode);JSONObject shared=ManualWatched.records(c).getJSONObject("tt99003001");HomeRegression.check(shared.getBoolean("watched"),"Desktop manual selection did not reach Android");Catalog.Title remote=Catalog.parse(shared.getJSONObject("title"),"animes");ManualWatched.set(c,remote,false);ManualWatched.sync(c,test.manualSyncCode);HomeRegression.check(beforeSync.toString().equals(WatchProgress.records(c).toString()),"Manual sync changed playback positions");}
 Bundle b=new Bundle();b.putString("result","PASS: Watched/Unwatched native controls preserve resume, initial native low-memory settings, busy-start rejection without queuing; optional live encrypted manual exchange");return b;
 }finally{if(session!=null)session.stop();StreamService.startupOwner=null;WatchSync.pending=false;WatchSync.testPairingCode=null;HomeLibrary.clear();if(main[0]!=null)test.runOnMainSync(()->main[0].finish());}}
}
